CREATE TABLE IF NOT EXISTS "member_user"
(
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY COMMENT '编号',
    "nickname"    varchar(30)  NOT NULL DEFAULT '' COMMENT '用户昵称',
    "name"        varchar(30)  NULL COMMENT '真实名字',
    sex           tinyint      null comment '性别',
    birthday      datetime     null comment '出生日期',
    area_id       int          null comment '所在地',
    mark          varchar(255) null comment '用户备注',
    point         int                   default 0 null comment '积分',
    "avatar"      varchar(255) NOT NULL DEFAULT '' COMMENT '头像',
    "status"      tinyint      NOT NULL COMMENT '状态',
    "mobile"      varchar(11)  NOT NULL COMMENT '手机号',
    "email"       varchar(50)  NULL COMMENT '邮箱',
    "password"    varchar(100) NOT NULL DEFAULT '' COMMENT '密码',
    "register_ip" varchar(32)  NOT NULL COMMENT '注册 IP',
    "register_terminal" tinyint NULL   DEFAULT NULL COMMENT '注册终端',
    "login_ip"    varchar(50)  NULL     DEFAULT '' COMMENT '最后登录IP',
    "login_date"  datetime     NULL     DEFAULT NULL COMMENT '最后登录时间',
    "tag_ids"     varchar(255) NULL     DEFAULT NULL COMMENT '用户标签编号列表,以逗号分隔',
    "level_id"    bigint       NULL     DEFAULT NULL COMMENT '等级编号',
    "experience"  bigint       NULL     DEFAULT NULL COMMENT '经验',
    "group_id"    bigint       NULL     DEFAULT NULL COMMENT '用户分组编号',
    "creator"     varchar(64)  NULL     DEFAULT '' COMMENT '创建者',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    "updater"     varchar(64)  NULL     DEFAULT '' COMMENT '更新者',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    "deleted"     bit(1)       NOT NULL DEFAULT '0' COMMENT '是否删除',
    "tenant_id"   bigint       not null default '0',
    PRIMARY KEY ("id")
) COMMENT '会员表';

CREATE TABLE IF NOT EXISTS "member_address" (
    "id" bigint(20) NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint(20) NOT NULL,
    "name" varchar(10) NOT NULL,
    "mobile" varchar(20) NOT NULL,
    "area_id" bigint(20) NOT NULL,
    "detail_address" varchar(250) NOT NULL,
    "default_status" bit NOT NULL,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "updater" varchar(64) DEFAULT '',
    PRIMARY KEY ("id")
) COMMENT '用户收件地址';

CREATE TABLE IF NOT EXISTS "member_tag"
(
    "id"          bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar  NOT NULL,
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    "tenant_id"   bigint   NOT NULL default '0',
    PRIMARY KEY ("id")
) COMMENT '会员标签';

CREATE TABLE IF NOT EXISTS "member_level"
(
    "id"             bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"           varchar  NOT NULL,
    "experience"     int      NOT NULL,
    "level"          int      NOT NULL,
    "discount_percent"       int      NOT NULL,
    "icon"           varchar  NOT NULL,
    "background_url" varchar  NOT NULL,
    "creator"        varchar           DEFAULT '',
    "create_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar           DEFAULT '',
    "update_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    "status" tinyint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT '会员等级';

CREATE TABLE IF NOT EXISTS "member_group"
(
    "id"          bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar  NOT NULL,
    "remark"      varchar  NOT NULL,
    "status" tinyint NOT NULL DEFAULT '0',
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    PRIMARY KEY ("id")
) COMMENT '用户分组';
CREATE TABLE IF NOT EXISTS "member_brokerage_record"
(
    "id"            int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "biz_id"        varchar  NOT NULL,
    "biz_type"      varchar  NOT NULL,
    "title"         varchar  NOT NULL,
    "price"         int      NOT NULL,
    "total_price"   int      NOT NULL,
    "description"   varchar  NOT NULL,
    "status"        varchar  NOT NULL,
    "frozen_days"   int      NOT NULL,
    "unfreeze_time" varchar,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    "tenant_id"      bigint   not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金记录';

CREATE TABLE IF NOT EXISTS "member_point_record"
(
    "id"          bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"     bigint        NOT NULL,
    "biz_id"      varchar(255)  NOT NULL,
    "biz_type"    tinyint       NOT NULL,
    "title"       varchar(255)  NOT NULL,
    "description" varchar(5000) NULL,
    "point"       int           NOT NULL,
    "total_point" int           NOT NULL,
    "creator"     varchar(64)            DEFAULT '',
    "create_time" datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)            DEFAULT '',
    "update_time" datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit           NOT NULL DEFAULT FALSE,
    "tenant_id"   bigint        NOT NULL default '0',
    PRIMARY KEY ("id")
) COMMENT '用户积分记录';

-- ========== 会员权益与奖金制度（bonus） ==========

CREATE TABLE IF NOT EXISTS "member_gift_config" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar(64)  NOT NULL DEFAULT '',
    "level_name"  varchar(64)  NOT NULL DEFAULT '',
    "price"       int          NOT NULL,
    "pv_percent"  int          NOT NULL DEFAULT 60,
    "spu_id"      bigint       NULL DEFAULT NULL,
    "icon"        varchar(255) NULL DEFAULT '',
    "sort"        int          NOT NULL DEFAULT 0,
    "status"      tinyint      NOT NULL DEFAULT 0,
    "remark"      varchar(255) NULL DEFAULT '',
    "creator"     varchar(64)  NULL DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  NULL DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '会员礼包配置';

CREATE TABLE IF NOT EXISTS "member_gift_benefit" (
    "id"              bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"         bigint       NOT NULL,
    "gift_id"         bigint       NOT NULL,
    "order_id"        bigint       NOT NULL,
    "order_no"        varchar(64)  NOT NULL DEFAULT '',
    "type"            tinyint      NOT NULL,
    "pay_amount"      int          NOT NULL DEFAULT 0,
    "paid_amount"     int          NOT NULL DEFAULT 0,
    "added_amount"    int          NOT NULL DEFAULT 0,
    "pv"              int          NOT NULL DEFAULT 0,
    "reversal_amount" int          NOT NULL DEFAULT 0,
    "reversal_pv"     int          NOT NULL DEFAULT 0,
    "status"          tinyint      NOT NULL DEFAULT 1,
    "effect_time"     datetime     NOT NULL,
    "creator"         varchar(64)  NULL DEFAULT '',
    "create_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)  NULL DEFAULT '',
    "update_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"       bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_gift_benefit_order" UNIQUE ("order_id")
) COMMENT '会员礼包权益记录';

CREATE TABLE IF NOT EXISTS "member_relation" (
    "id"             bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"        bigint       NOT NULL,
    "referrer_id"    bigint       NULL DEFAULT NULL,
    "bind_time"      datetime     NULL DEFAULT NULL,
    "valid_buy_time" datetime     NULL DEFAULT NULL,
    "valid_seq"      int          NULL DEFAULT NULL,
    "boss_time"      datetime     NULL DEFAULT NULL,
    "market_id"      bigint       NULL DEFAULT NULL,
    "creator"        varchar(64)  NULL DEFAULT '',
    "create_time"    datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar(64)  NULL DEFAULT '',
    "update_time"    datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"      bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_relation_user" UNIQUE ("user_id")
) COMMENT '会员推荐关系';

CREATE TABLE IF NOT EXISTS "member_market" (
    "id"            bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "owner_user_id" bigint       NOT NULL,
    "effect_time"   datetime     NOT NULL,
    "status"        tinyint      NOT NULL DEFAULT 1,
    "creator"       varchar(64)  NULL DEFAULT '',
    "create_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar(64)  NULL DEFAULT '',
    "update_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"     bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_market_owner" UNIQUE ("owner_user_id")
) COMMENT '会员市场';

CREATE TABLE IF NOT EXISTS "member_market_history" (
    "id"             bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"        bigint       NOT NULL,
    "from_market_id" bigint       NULL DEFAULT NULL,
    "to_market_id"   bigint       NOT NULL,
    "effect_time"    datetime     NOT NULL,
    "reason"         varchar(255) NULL DEFAULT '',
    "creator"        varchar(64)  NULL DEFAULT '',
    "create_time"    datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar(64)  NULL DEFAULT '',
    "update_time"    datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"      bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '会员市场归属变更历史';

CREATE TABLE IF NOT EXISTS "member_director" (
    "id"           bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"      bigint       NOT NULL,
    "level"        tinyint      NOT NULL,
    "qualify_time" datetime     NOT NULL,
    "status"       tinyint      NOT NULL DEFAULT 1,
    "source"       varchar(255) NULL DEFAULT '',
    "creator"      varchar(64)  NULL DEFAULT '',
    "create_time"  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"      varchar(64)  NULL DEFAULT '',
    "update_time"  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"      bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"    bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_director_user_level" UNIQUE ("user_id", "level")
) COMMENT '会员董事资格';

CREATE TABLE IF NOT EXISTS "member_bonus_config" (
    "id"                           bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "pv_percent"                   int          NOT NULL DEFAULT 60,
    "direct_first_rate"            int          NOT NULL DEFAULT 30,
    "direct_after_rate"            int          NOT NULL DEFAULT 55,
    "increment_rate"               int          NOT NULL DEFAULT 25,
    "help_rate"                    int          NOT NULL DEFAULT 20,
    "director_one_rate"            int          NOT NULL DEFAULT 10,
    "director_two_rate"            int          NOT NULL DEFAULT 7,
    "director_three_rate"          int          NOT NULL DEFAULT 5,
    "director_four_rate"           int          NOT NULL DEFAULT 3,
    "director_five_rate"           int          NOT NULL DEFAULT 2,
    "gift_pool_percent"            int          NOT NULL DEFAULT 60,
    "gift_income_source"           varchar(32)  NOT NULL DEFAULT 'DISABLED',
    "director_qualify_gift_id"     bigint       NULL DEFAULT NULL,
    "director_one_star_count"      int          NOT NULL DEFAULT 6,
    "director_qualify_scope"       varchar(32)  NOT NULL DEFAULT 'DIRECT',
    "director_trainee_scope"       varchar(32)  NOT NULL DEFAULT 'DIRECT',
    "director_two_star_trainees"   int          NOT NULL DEFAULT 1,
    "director_three_star_trainees" int          NOT NULL DEFAULT 2,
    "director_four_star_trainees"  int          NOT NULL DEFAULT 4,
    "director_five_star_trainees"  int          NOT NULL DEFAULT 6,
    "empty_level_policy"           varchar(32)  NOT NULL DEFAULT 'KEEP',
    "observe_days"                 int          NOT NULL DEFAULT 0,
    "settle_day"                   int          NULL DEFAULT NULL,
    "pay_day"                      int          NULL DEFAULT NULL,
    "rounding_mode"                varchar(16)  NOT NULL DEFAULT 'HALF_UP',
    "reversal_policy"              varchar(32)  NOT NULL DEFAULT 'RECORD_ONLY',
    "product_pool_percent"         int          NOT NULL DEFAULT 10,
    "gmv_include_delivery"         tinyint      NOT NULL DEFAULT 0,
    "version"                      int          NOT NULL DEFAULT 1,
    "remark"                       varchar(255) NULL DEFAULT '',
    "creator"                      varchar(64)  NULL DEFAULT '',
    "create_time"                  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                      varchar(64)  NULL DEFAULT '',
    "update_time"                  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"                      bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"                    bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '奖金规则配置';

CREATE TABLE IF NOT EXISTS "member_bonus_record" (
    "id"              bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "dedup_key"       varchar(128)  NOT NULL,
    "user_id"         bigint        NOT NULL,
    "bonus_type"      tinyint       NOT NULL,
    "source_user_id"  bigint        NULL DEFAULT NULL,
    "source_order_id" bigint        NULL DEFAULT NULL,
    "base_pv"         int           NOT NULL DEFAULT 0,
    "base_amount"     int           NOT NULL DEFAULT 0,
    "rate"            int           NOT NULL DEFAULT 0,
    "amount"          int           NOT NULL DEFAULT 0,
    "market_id"       bigint        NULL DEFAULT NULL,
    "director_level"  tinyint       NULL DEFAULT NULL,
    "period"          varchar(7)    NOT NULL DEFAULT '',
    "rule_version"    int           NOT NULL DEFAULT 1,
    "status"          tinyint       NOT NULL DEFAULT 10,
    "settle_batch_no" varchar(32)   NULL DEFAULT NULL,
    "reversal_of_id"  bigint        NULL DEFAULT NULL,
    "reversal_reason" varchar(255)  NULL DEFAULT '',
    "creator"         varchar(64)   NULL DEFAULT '',
    "create_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)   NULL DEFAULT '',
    "update_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit(1)        NOT NULL DEFAULT '0',
    "tenant_id"       bigint        NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_bonus_record_dedup" UNIQUE ("dedup_key")
) COMMENT '会员礼包奖金明细';

CREATE TABLE IF NOT EXISTS "member_bonus_settle_batch" (
    "id"              bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "batch_no"        varchar(32)   NOT NULL,
    "period"          varchar(7)    NOT NULL,
    "scope"           varchar(16)   NOT NULL DEFAULT 'GIFT',
    "status"          tinyint       NOT NULL DEFAULT 10,
    "dividend_pool"   int           NOT NULL DEFAULT 0,
    "total_amount"    int           NOT NULL DEFAULT 0,
    "user_count"      int           NOT NULL DEFAULT 0,
    "config_snapshot" varchar(4096) NULL DEFAULT '',
    "remark"          varchar(1024) NULL DEFAULT '',
    "creator"         varchar(64)   NULL DEFAULT '',
    "create_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)   NULL DEFAULT '',
    "update_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit(1)        NOT NULL DEFAULT '0',
    "tenant_id"       bigint        NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_settle_batch_period" UNIQUE ("period", "scope"),
    CONSTRAINT "uk_settle_batch_no" UNIQUE ("batch_no")
) COMMENT '会员礼包奖金结算批次';

CREATE TABLE IF NOT EXISTS "member_bonus_settle_detail" (
    "id"            bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "batch_no"      varchar(32)  NOT NULL,
    "user_id"       bigint       NOT NULL,
    "total_amount"  int          NOT NULL DEFAULT 0,
    "pay_status"    tinyint      NOT NULL DEFAULT 10,
    "wallet_biz_id" varchar(64)  NULL DEFAULT NULL,
    "pay_time"      datetime     NULL DEFAULT NULL,
    "creator"       varchar(64)  NULL DEFAULT '',
    "create_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar(64)  NULL DEFAULT '',
    "update_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit(1)       NOT NULL DEFAULT '0',
    "tenant_id"     bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_settle_detail_batch_user" UNIQUE ("batch_no", "user_id")
) COMMENT '会员礼包奖金结算个人明细';
